import { Code, ConnectError, createClient, type Client } from "@connectrpc/connect"
import { trace } from "@opentelemetry/api"

import type { Env } from "../env"
import { GitRead } from "../gen/gitread/v1/gitread_pb"
import { FLAG_REPO_SOURCE_GO_GIT_API } from "./constants"
import { fetchFileAtCommit } from "./github"
import { createGoGitApiTransport } from "./go-git-api"
import { getOrCreatePostHogClient, isFeatureEnabled } from "./posthog"

const textDecoder = new TextDecoder()

const FALLBACK_CONNECT_CODES = new Set<Code>([
  Code.NotFound,
  Code.Unavailable,
  Code.DeadlineExceeded,
  Code.Canceled,
])

// Translates upstream Connect failures into a fallback signal. Codes outside
// FALLBACK_CONNECT_CODES (Internal, InvalidArgument, Unimplemented, …) and
// non-Connect errors propagate untouched so real bugs aren't silently masked
// by GitHub fallback.
function throwAsRepoProviderUnavailable(err: unknown): never {
  if (err instanceof ConnectError && FALLBACK_CONNECT_CODES.has(err.code)) {
    throw new RepoProviderUnavailableError(
      err.code === Code.NotFound ? "repo_or_ref_not_found" : "connect_unavailable",
    )
  }
  throw err
}

/**
 * Per-path resilience hook: invoked when a single path's fetch failed
 * transiently (rate limit, 5xx, connection error). The path's entry in
 * the returned Map is `null` either way; the callback is what lets a
 * caller distinguish "path is genuinely missing" (404) from "path was
 * unreadable this attempt" (transient) so partial-success can preserve
 * `hadTransientError` semantics.
 */
export interface GetFilesOptions {
  onTransientPath?: (path: string) => void
}

export interface RepoReadProvider {
  getFileAtCommit(
    repoFullName: string,
    path: string,
    sha: string,
    accessToken?: string,
  ): Promise<string | null>
  getFilesAtCommit(
    repoFullName: string,
    paths: string[],
    sha: string,
    accessToken?: string,
    options?: GetFilesOptions,
  ): Promise<Map<string, string | null>>
}

export const githubRepoProvider: RepoReadProvider = {
  getFileAtCommit: fetchFileAtCommit,
  async getFilesAtCommit(repoFullName, paths, sha, accessToken, options) {
    const result = new Map<string, string | null>()
    if (paths.length === 0) return result
    // Promise.allSettled (not Promise.all) so a single transient failure
    // doesn't kill the whole batch. Per-path rejections become null + a
    // callback fire; the caller decides whether to treat that as "missing"
    // (worker retries handle eventual recovery) or "transient" (so derived
    // dead-session state isn't persisted on a flaky read).
    const settled = await Promise.allSettled(
      paths.map((p) => fetchFileAtCommit(repoFullName, p, sha, accessToken)),
    )
    paths.forEach((p, i) => {
      const r = settled[i]
      if (r.status === "fulfilled") {
        result.set(p, r.value)
      } else {
        result.set(p, null)
        options?.onTransientPath?.(p)
      }
    })
    return result
  },
}

type RepoProviderUnavailableReason =
  | "invalid_repo_full_name"
  | "connect_unavailable"
  | "repo_or_ref_not_found"
  | "file_too_large"

// Caught by wrapWithGitHubFallback; anything else propagates.
class RepoProviderUnavailableError extends Error {
  constructor(public reason: RepoProviderUnavailableReason) {
    super(`Repo provider unavailable: ${reason}`)
    this.name = "RepoProviderUnavailableError"
  }
}

type RepoFile = {
  path: string
  content: Uint8Array
  notFound: boolean
  tooLarge: boolean
}

// Shared pipeline for Connect-backed providers: split owner/repo, run the
// RPC (mapping fallback errors), then index the response by path and decode
// every requested path. Differences between providers are confined to the
// `callRpc` callback (request shape + transport-specific call options).
async function readFilesViaConnect(
  repoFullName: string,
  paths: string[],
  callRpc: (owner: string, repo: string) => Promise<{ files: readonly RepoFile[] }>,
): Promise<Map<string, string | null>> {
  const result = new Map<string, string | null>()
  if (paths.length === 0) return result
  const [owner, repo] = repoFullName.split("/", 2)
  if (!owner || !repo) {
    throw new RepoProviderUnavailableError("invalid_repo_full_name")
  }
  let response: { files: readonly RepoFile[] }
  try {
    response = await callRpc(owner, repo)
  } catch (err) {
    throwAsRepoProviderUnavailable(err)
  }
  const byPath = new Map<string, RepoFile>()
  for (const file of response.files) byPath.set(file.path, file)
  for (const path of paths) {
    const file = byPath.get(path)
    if (!file || file.notFound) {
      result.set(path, null)
      continue
    }
    if (file.tooLarge) {
      throw new RepoProviderUnavailableError("file_too_large")
    }
    result.set(path, textDecoder.decode(file.content))
  }
  return result
}

export type GitReadClient = Client<typeof GitRead>

function createGitReadClient(env: Env): GitReadClient {
  return createClient(GitRead, createGoGitApiTransport(env))
}

// go-git-api forwards the inbound Authorization header VERBATIM to the
// upstream Git remote. GitHub's git smart-HTTP endpoint authenticates via
// HTTP Basic where the password is the installation token (username can be
// anything; the documented convention is "x-access-token") — NOT Bearer.
// Sending Bearer here would land at gitread, get forwarded as-is, and
// GitHub would 401 it. We pre-encode Basic so the forwarded header
