/**
 * Compute the session indices that had no transcript content. Pass the checkpoint's
 * known session count (from metadata) and the `fetchAndStripTranscripts` sessions map.
 * Returns `[]` when every session has content; passing `[]` to `updateTranscriptBatch`
 * clears any prior dead-index record on the row.
 *
 * Clamped to `MAX_SESSIONS_PER_CHECKPOINT` — fetchAndStripTranscripts caps its fan-out at
 * the same limit, so sessions beyond the cap were never attempted and must not be marked
 * dead on that basis.
 */
export function computeDeadSessionIndices(
  sessionCount: number,
  transcripts: Record<string, StoredTranscriptSession> | null,
): number[] {
  const effectiveCount = Math.min(Math.max(sessionCount, 0), MAX_SESSIONS_PER_CHECKPOINT)
  const dead: number[] = []
  for (let i = 0; i < effectiveCount; i++) {
    if (!transcripts || !transcripts[String(i)]) dead.push(i)
  }
  return dead
}

