// Handler for user checkpoints — used by both session-auth and bearer-auth routes
export async function handleUserCheckpoints(c: Context<{ Bindings: Env; Variables: Variables }>) {
  const userId = requireUserId(c)
  const { timeframe, limit, startDate, endDate } = parseTimeframeParams(c)

  try {
    const db = getDb(c.env)
    const user = await db.users.getWithCache(c.env.ENTIRE_CACHE, userId)
    if (!user) {
      return c.json({ error: "User not found" }, 404)
    }

    const pendingSyncCount = await db.repos.countPendingSync(userId)
    const syncing = (pendingSyncCount ?? 0) > 0

    const [checkpoints, streakDates] = await Promise.all([
      db.checkpoints.getByUser(
        userId,
        user.github_id,
        startDate.toISOString(),
        endDate.toISOString(),
        limit,
      ),
      db.checkpoints.getStreakTimestamps(userId, user.github_id),
    ])

    return c.json({
      checkpoints,
      streakDates,
      timeframe,
      updated_at: new Date().toISOString(),
      syncing,
    })
  } catch (err) {
    console.error("Failed to fetch user checkpoints:", err)
    recordSpanError(err)
    return c.json({ error: "Failed to fetch checkpoints" }, 500)
  }
}

