function encodeSessionsCursor(cursor: SessionsListCursor): string {
  const json = JSON.stringify(cursor)
  return btoa(json).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "")
}

function decodeSessionsCursor(value: string): SessionsListCursor | null {
  try {
    const padded = value
      .replace(/-/g, "+")
      .replace(/_/g, "/")
      .padEnd(value.length + ((4 - (value.length % 4)) % 4), "=")
    const decoded = atob(padded)
    const parsed = JSON.parse(decoded) as Partial<SessionsListCursor>
    if (typeof parsed?.lastActivityAt !== "string" || typeof parsed?.sessionId !== "string") {
      return null
    }
    return { lastActivityAt: parsed.lastActivityAt, sessionId: parsed.sessionId }
  } catch {
    return null
  }
}

