  if (uniqueCheckpointIds.length === 0) return
  const lockKey = `${repo.id}:${uniqueCheckpointIds.slice().sort().join(",")}`
  if (inFlightCheckpointHydrations.has(lockKey)) return

  const task = async () => {
    try {
      let token = await getInstallationTokenForRepo(db, c.env, repo)
      if (!token && userId) {
        const tokenResult = await getGitHubTokenForRepoRequest(c, db, userId, repo)
        if (tokenResult.response) {
          console.warn(
            `[checkpoint-hydration] skipped repo=${repo.full_name} checkpoints=${uniqueCheckpointIds.join(",")} reason=oauth_unavailable`,
          )
          return
        }
        token = tokenResult.token ?? undefined
      }
      if (!token) {
        console.warn(
          `[checkpoint-hydration] skipped repo=${repo.full_name} checkpoints=${uniqueCheckpointIds.join(",")} reason=no_token`,
        )
        return
      }

      await hydrateCheckpointPayloads(c.env, db, repo, uniqueCheckpointIds, token, {
        fallbackBranch: options?.fallbackBranch ?? null,
        onError: (err, meta) => {
          console.error(
            `[checkpoint-hydration] repo=${repo.full_name} checkpoints=${uniqueCheckpointIds.join(",")} stage=${String(meta.stage ?? "unknown")}`,
            err,
          )
        },
      })
    } catch (err) {
      console.error(
        `[checkpoint-hydration] failed repo=${repo.full_name} checkpoints=${uniqueCheckpointIds.join(",")}`,
        err,
      )
    } finally {
      inFlightCheckpointHydrations.delete(lockKey)
    }
  }

  inFlightCheckpointHydrations.set(lockKey, task())
  await runInBackground(c, async () => inFlightCheckpointHydrations.get(lockKey))
}

