function extractSessionEnvelopeMeta(
  checkpoints: Awaited<ReturnType<Db["checkpoints"]["getForSession"]>>,
  merged: ReturnType<typeof mergeSessionTranscript>,
  sessionId: string,
): SessionEnvelopeMeta {
  let prompt: string | null = null
  let model: string | null = null
  let steps = 0
  let createdAt: string | null = null
  let checkpointCount = 0
  let agentFromMetadata: string | null = null
  const envelopeCheckpoints: SessionEnvelopeCheckpoint[] = []

  for (let i = 0; i < merged.checkpointSessionsInfo.length; i++) {
    const info = merged.checkpointSessionsInfo[i]
    if (!info) continue
    const meta = info.find((s) => s.sessionId === sessionId)
    if (!meta) continue

    const metaAny = meta as typeof meta & {
      prompt?: string | null
      model?: string | null
      steps?: number
      createdAt?: string
    }
    if (agentFromMetadata === null && typeof meta.agent === "string") {
      agentFromMetadata = meta.agent
    }
    if (prompt === null && typeof metaAny.prompt === "string") prompt = metaAny.prompt
    if (model === null && typeof metaAny.model === "string") model = metaAny.model
    if (typeof metaAny.steps === "number") steps += metaAny.steps
    if (typeof metaAny.createdAt === "string") {
      if (createdAt === null || metaAny.createdAt < createdAt) createdAt = metaAny.createdAt
    }

    // Only emit a checkpoint card when commit metadata is present.
    // `checkpointCount` tracks visible cards so the header stays in sync
    // with the rendered list — a DB row with a null commit_sha would
    // otherwise drift them.
    const cp = checkpoints[i]
    if (typeof cp.commit_sha === "string" && typeof cp.commit_date === "string") {
      checkpointCount++
      envelopeCheckpoints.push({
        checkpointId: cp.checkpoint_id,
        commitSha: cp.commit_sha,
        message: cp.commit_message ?? "",
        additions: cp.additions ?? 0,
        deletions: cp.deletions ?? 0,
        filesChanged: cp.files_changed ?? 0,
        timestamp: cp.commit_date,
        authorUsername: cp.commit_author_username ?? null,
      })
    }
  }

  return {
    session: {
      agent: agentFromMetadata ?? merged.agent,
      prompt,
      model,
      steps,
      checkpointCount,
      createdAt,
    },
    checkpoints: envelopeCheckpoints,
    tokenUsage: merged.tokenUsage ?? { inputTokens: 0, outputTokens: 0 },
