 */
export function mapCheckpointToTrailSummary(row: CheckpointWithCommit): TrailCheckpointSummary {
  const sessions = filterLiveSessions(parseSessionsFromRow(row), row.dead_session_indices)
  const agents = [...new Set(sessions.map((s) => s.agent))]
  return {
    commitSha: row.commit_sha,
    commitMessage: row.commit_message,
